mapper.select:
        select g.id, g.mix_area, g.machine_code, m.machine_name, g.glue, g.remark, g.del_flag, g.create_by, g.create_time, g.update_by, g.update_time
          from t_glue_common_demand g
          left join t_mix_machine m
            on m.del_flag = '0'
           and m.machine_code = g.machine_code
           and m.mix_area = g.mix_area
         where g.del_flag = '0'
	     and m.mix_area = #{mixArea}
	     and m.machine_code = #{machineCode}
	     and g.glue = #{glue}

         order by mix_area, machine_name


         order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea} mixArea, #{data.machineCode} machineCode, #{data.glue} glue
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_common_demand m inner join temp_table t on m.mix_area = t.mixArea and m.machine_Code = t.machineCode and m.glue = t.glue and m.del_flag ='0'

mapper.insert:
insert into t_glue_common_demand (id,mix_area,machine_code,glue,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{glueCommonDemand.mixArea,jdbcType= VARCHAR} mix_area, #{glueCommonDemand.machineCode,jdbcType= VARCHAR} machine_code, #{glueCommonDemand.glue,jdbcType= VARCHAR} glue, #{glueCommonDemand.remark,jdbcType= VARCHAR} remark, #{glueCommonDemand.delFlag,jdbcType= VARCHAR} del_flag, #{glueCommonDemand.createBy,jdbcType= VARCHAR} create_by, #{glueCommonDemand.createTime,jdbcType=TIMESTAMP} create_time, #{glueCommonDemand.updateBy,jdbcType= VARCHAR} update_by, #{glueCommonDemand.updateTime,jdbcType=TIMESTAMP} update_time
) x
